style.css:
@-moz-document domain("youtube.com") {
/* Fondo general */
  body {
    background: #C0C0C0 !important; /* gris clásico de XP */
    color: black !important;
    font-family: Tahoma, Verdana, Arial, sans-serif !important;
  }

  /* Barra superior (imitando el header de ventana XP) */
  #masthead-container {
    background: linear-gradient(to bottom, #003C74, #245C9A) !important;
    border-bottom: 2px solid #08216B !important;
    height: 45px !important;
  }

  #logo-icon {
    filter: grayscale(100%) brightness(200%) contrast(80%) !important;
  }

  /* Botones estilo XP */
  button,
  yt-icon-button,
  .yt-simple-endpoint {
    background: #E0E0E0 !important;
    border: 1px solid #808080 !important;
    border-radius: 0px !important;
    padding: 3px 6px !important;
    font-size: 12px !important;
    font-family: Tahoma, sans-serif !important;
  }

  button:hover,
  yt-icon-button:hover {
    background: #316AC5 !important;
    color: white !important;
    border: 1px solid #08216B !important;
  }

  /* Barra lateral */
  #guide-content {
    background: #D4D0C8 !important;
    border-right: 2px solid #808080 !important;
  }

  /* Caja de búsqueda estilo XP */
  #search-input {
    background: #FFFFFF !important;
    border: 2px inset #808080 !important;
    font-family: Tahoma, sans-serif !important;
    font-size: 12px !important;
    padding: 2px !important;
  }

  /* Videos miniatura */
  ytd-rich-grid-media {
    background: #ECE9D8 !important;
    border: 2px solid #808080 !important;
    margin: 4px !important;
    padding: 6px !important;
  }

  /* Footer */
  ytd-mini-guide-renderer {
    background: #D4D0C8 !important;
  }

  /* Scroll estilo XP */
  ::-webkit-scrollbar {
    width: 16px;
    background: #D4D0C8;
  }
  ::-webkit-scrollbar-thumb {
    background: #C0C0C0;
    border: 2px solid #808080;
  }
}
